use serde::{Deserialize, Serialize};

/// What an artifact holds. Drives renderer choice; the body is always text on
/// the wire (a binary artifact carries a reference, not bytes).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ArtifactKind {
    /// Plain text.
    Text,
    /// Markdown source.
    Markdown,
    /// A reference to a generated image (URL or workspace path, not bytes).
    Image,
    /// A reference to a generated file (workspace path, not bytes).
    File,
    /// A presentation (e.g. .pptx / Google Slides).
    Presentation,
    /// A document (e.g. .docx / Google Docs).
    Document,
}

impl ArtifactKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            ArtifactKind::Text => "text",
            ArtifactKind::Markdown => "markdown",
            ArtifactKind::Image => "image",
            ArtifactKind::File => "file",
            ArtifactKind::Presentation => "presentation",
            ArtifactKind::Document => "document",
        }
    }

    /// Parse from a string. Case-insensitive; falls back to `Text`.
    pub fn parse(raw: &str) -> Self {
        match raw.to_ascii_lowercase().as_str() {
            "markdown" | "md" => Self::Markdown,
            "image" | "img" | "png" | "jpg" | "jpeg" | "gif" | "svg" => Self::Image,
            "file" => Self::File,
            "presentation" | "pptx" | "slides" => Self::Presentation,
            "document" | "docx" | "doc" => Self::Document,
            _ => Self::Text,
        }
    }
}

/// Who produced a version.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ArtifactAuthor {
    /// An agent turn produced it.
    Agent,
    /// A human edited it (typically just before approving).
    Operator,
    /// A system process (migration, auto-save, etc.).
    System,
}

/// Lifecycle status of a pending artifact being produced.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ArtifactStatus {
    /// Being generated by a producer tool.
    Pending,
    /// Fully written and ready.
    Ready,
    /// Generation failed.
    Failed,
}

impl ArtifactStatus {
    pub fn as_str(&self) -> &'static str {
        match self {
            ArtifactStatus::Pending => "pending",
            ArtifactStatus::Ready => "ready",
            ArtifactStatus::Failed => "failed",
        }
    }
}

/// One immutable revision of an artifact.
///
/// Versions are append-only and 1-based. A version is never edited in place —
/// an operator's change appends a new one — so the full provenance chain
/// survives.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ArtifactVersion {
    /// 1-based revision number, contiguous within the artifact.
    pub version: u32,
    /// The revision's content.
    pub body: String,
    /// Whether an agent or a human wrote this revision.
    pub author: ArtifactAuthor,
    /// The agent id, or the operator's label. Free-form and display-only.
    pub author_id: String,
    /// Epoch-millis the revision was recorded.
    pub created_at_millis: u64,
    /// Why this revision exists (e.g. `"operator edit before approval"`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
    /// The on-disk path to the binary content, when the body is a reference
    /// rather than inline text.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub file_path: Option<String>,
}

/// A versioned output.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ArtifactRecord {
    /// Stable id within the store.
    pub id: String,
    /// Optional owning task or workflow id.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub task_id: Option<String>,
    /// A short display title.
    pub title: String,
    /// What it holds.
    pub kind: ArtifactKind,
    /// Every revision, oldest first.
    pub versions: Vec<ArtifactVersion>,
    /// Epoch-millis the artifact was first created.
    pub created_at_millis: u64,
    /// Epoch-millis of the newest revision.
    pub updated_at_millis: u64,
    /// Lifecycle status (for in-progress producer tools).
    #[serde(default)]
    pub status: ArtifactStatus,
    /// The workspace-relative path this artifact was published from.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source: Option<String>,
}

impl ArtifactRecord {
    /// Creates an artifact with its first (agent-authored) version.
    pub fn new(
        id: impl Into<String>,
        kind: ArtifactKind,
        title: impl Into<String>,
        body: impl Into<String>,
        author_id: impl Into<String>,
        at_millis: u64,
    ) -> Self {
        let body = body.into();
        Self {
            id: id.into(),
            task_id: None,
            title: title.into(),
            kind,
            versions: vec![ArtifactVersion {
                version: 1,
                body,
                author: ArtifactAuthor::Agent,
                author_id: author_id.into(),
                created_at_millis: at_millis,
                note: None,
                file_path: None,
            }],
            created_at_millis: at_millis,
            updated_at_millis: at_millis,
            status: ArtifactStatus::Ready,
            source: None,
        }
    }

    /// The newest revision, or `None` on an empty record.
    pub fn latest(&self) -> Option<&ArtifactVersion> {
        self.versions.last()
    }

    /// A revision by its 1-based number.
    pub fn version(&self, version: u32) -> Option<&ArtifactVersion> {
        self.versions.iter().find(|v| v.version == version)
    }

    /// Appends a revision, numbering it after the current newest and advancing
    /// `updated_at_millis`. Returns the new version number.
    pub fn push_version(
        &mut self,
        body: impl Into<String>,
        author: ArtifactAuthor,
        author_id: impl Into<String>,
        at_millis: u64,
        note: Option<String>,
    ) -> u32 {
        let next = self.versions.iter().map(|v| v.version).max().unwrap_or(0) + 1;
        self.versions.push(ArtifactVersion {
            version: next,
            body: body.into(),
            author,
            author_id: author_id.into(),
            created_at_millis: at_millis,
            note,
            file_path: None,
        });
        self.updated_at_millis = at_millis;
        self.status = ArtifactStatus::Ready;
        next
    }

    /// The number of versions.
    pub fn version_count(&self) -> u32 {
        self.versions.len() as u32
    }
}

/// Error type for artifact operations.
#[derive(Debug, thiserror::Error)]
pub enum ArtifactError {
    #[error("artifact not found: {0}")]
    NotFound(String),
    #[error("artifact already exists: {0}")]
    AlreadyExists(String),
    #[error("storage error: {0}")]
    Storage(String),
    #[error("invalid argument: {0}")]
    InvalidArgument(String),
}